-- Build #93 Pacific feeds (data only, MEDIUM). Generated by Build-Sql.py. Reverse: reverse.sql.
\set ON_ERROR_STOP on
SET lock_timeout = '5s';
SET statement_timeout = '120s';
BEGIN;
CREATE TEMP TABLE src (iso text, name text, homepage text, feed text, domain text, source_type text, note text) ON COMMIT DROP;
INSERT INTO src VALUES
  ('SB', 'Asia Pacific Report: Solomon Islands', 'https://asiapacificreport.nz', 'https://asiapacificreport.nz/category/pacific/solomon-islands/feed/', 'asiapacificreport.nz', 'ONLINE_NEWS', 'rss, 50 items, newest 6 d, 18 in 90 d'),
  ('TV', 'Asia Pacific Report: Tuvalu', 'https://asiapacificreport.nz', 'https://asiapacificreport.nz/category/pacific/tuvalu/feed/', 'asiapacificreport.nz', 'ONLINE_NEWS', 'rss, 50 items, newest 11 d, 4 in 90 d'),
  ('MH', 'Asia Pacific Report: Marshall Islands', 'https://asiapacificreport.nz', 'https://asiapacificreport.nz/category/pacific/marshall-islands/feed/', 'asiapacificreport.nz', 'ONLINE_NEWS', 'rss, 50 items, newest 19 d, 3 in 90 d'),
  ('KI', 'Asia Pacific Report: Kiribati', 'https://asiapacificreport.nz', 'https://asiapacificreport.nz/category/pacific/kiribati/feed/', 'asiapacificreport.nz', 'ONLINE_NEWS', 'rss, 50 items, newest 37 d, 4 in 90 d'),
  ('NR', 'Asia Pacific Report: Nauru', 'https://asiapacificreport.nz', 'https://asiapacificreport.nz/category/pacific/nauru/feed/', 'asiapacificreport.nz', 'ONLINE_NEWS', 'rss, 50 items, newest 37 d, 9 in 90 d'),
  ('PW', 'Island Times', 'https://islandtimes.org', 'https://islandtimes.org/feed/', 'islandtimes.org', 'NEWSPAPER', 'rss, 20 items, newest 2026-10-16');
CREATE TEMP TABLE rep (pub int, old_url text, new_url text) ON COMMIT DROP;
INSERT INTO rep VALUES
  (2070, 'https://asiapacificreport.nz/tag/vanuatu/feed/', 'https://asiapacificreport.nz/category/pacific/vanuatu/feed/'),
  (2072, 'https://asiapacificreport.nz/tag/samoa/feed/', 'https://asiapacificreport.nz/category/pacific/samoa/feed/'),
  (2076, 'https://asiapacificreport.nz/tag/micronesia/feed/', 'https://asiapacificreport.nz/category/pacific/federated-states-of-micronesia/feed/');
DO $$
DECLARE n int; bad int; s record; cid int; sid int; pid int;
BEGIN
  -- 1. the 7 placeholder rows: only if each is still exactly the PINA "No Feed Access" item
  DELETE FROM articles WHERE id = ANY(ARRAY[659188,659199,660947,661167,661176,663833,663646]) AND headline = 'No Feed Access' AND publisher_id = ANY(ARRAY[2069,2074,2075,2077,2079,2080,2081]);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 7 THEN RAISE EXCEPTION 'deleted % placeholder rows, expected 7', n; END IF;

  -- 2. PINA publishers off (their feeds only ever return the placeholder)
  UPDATE publishers SET feed_status = 'unavailable' WHERE id = ANY(ARRAY[2069,2074,2075,2077,2079,2080,2081]) AND feed_status = 'active';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 7 THEN RAISE EXCEPTION 'PINA: % publishers set unavailable, expected 7', n; END IF;
  UPDATE feeds SET enabled = false WHERE publisher_id = ANY(ARRAY[2069,2074,2075,2077,2079,2080,2081]) AND enabled;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 7 THEN RAISE EXCEPTION 'PINA: % feeds disabled, expected 7', n; END IF;

  -- 3. Asia Pacific Report tag feeds -> live category feeds (reset failure state so the new URL is polled at once)
  UPDATE feeds f SET feed_url = r.new_url, consecutive_failures = 0, last_error = NULL
    FROM rep r WHERE f.publisher_id = r.pub AND f.feed_url = r.old_url;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 3 THEN RAISE EXCEPTION 'repointed % APR feeds, expected 3', n; END IF;

  -- 4. new publishers (same refusal as findPublisherConflict, plus an earlier run of this script)
  SELECT count(*) INTO bad FROM src x JOIN countries c ON c.iso_code = x.iso
   WHERE EXISTS (SELECT 1 FROM publishers p WHERE p.country_id = c.id AND (lower(p.name) = lower(x.name)
                 OR lower(regexp_replace(regexp_replace(p.domain, '^www[.]', ''), '/+$', '')) = x.domain))
      OR EXISTS (SELECT 1 FROM feeds f WHERE f.feed_url = x.feed)
      OR EXISTS (SELECT 1 FROM publisher_submissions ps WHERE ps.verification_detail LIKE '%' || '[added by Claude 2026-10-18, Build #93 Pacific feeds]');
  IF bad > 0 THEN RAISE EXCEPTION '% of 6 already exist as a publisher, feed or earlier run - nothing changed', bad; END IF;
  n := 0;
  FOR s IN SELECT * FROM src ORDER BY iso LOOP
    SELECT id INTO cid FROM countries WHERE iso_code = s.iso;
    IF cid IS NULL THEN RAISE EXCEPTION 'no country %', s.iso; END IF;
    INSERT INTO publisher_submissions (name, homepage_url, feed_url, feed_type, country_id, language, feed_verified,
      verification_detail, domain, ingestion_method, status, status_changed_at, reviewed_at)
    VALUES (s.name, s.homepage, s.feed, 'rss', cid, 'en', true,
      'Feed checked 2026-10-18: ' || s.note || ' ' || '[added by Claude 2026-10-18, Build #93 Pacific feeds]', s.domain, 'feed', 'approved', now(), now())
    RETURNING id INTO sid;
    INSERT INTO publishers (country_id, name, homepage_url, feed_status, language, domain, source_type)
    VALUES (cid, s.name, s.homepage, 'active', 'en', s.domain, s.source_type) RETURNING id INTO pid;
    INSERT INTO feeds (publisher_id, feed_url, feed_type) VALUES (pid, s.feed, 'rss');
    UPDATE publisher_submissions SET publisher_id = pid WHERE id = sid;
    n := n + 1;
  END LOOP;
  IF n <> 6 THEN RAISE EXCEPTION 'added %, expected 6', n; END IF;
END $$;
SELECT 'added|' || p.id || '|' || c.iso_code || '|' || p.name || '|' || p.feed_status || '|' || f.feed_url
  FROM publisher_submissions s JOIN publishers p ON p.id = s.publisher_id JOIN feeds f ON f.publisher_id = p.id
  JOIN countries c ON c.id = p.country_id WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-18, Build #93 Pacific feeds]' ORDER BY c.iso_code;
SELECT 'repointed|' || f.publisher_id || '|' || f.feed_url FROM feeds f WHERE f.publisher_id IN (2070,2072,2076) ORDER BY 1;
SELECT 'coverage|' || c.iso_code || '|' || count(*) FILTER (WHERE p.feed_status = 'active') || ' active'
  FROM countries c JOIN publishers p ON p.country_id = c.id
 WHERE c.iso_code IN ('SB','KI','FM','PW','MH','NR','TV','WS','VU') GROUP BY c.iso_code ORDER BY 1;
COMMIT;
